import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const captureIntervalRef = useRef(null);
  const isProcessingRef = useRef(false);

  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(true);
  const [frameCount, setFrameCount] = useState(0);
  const [lastDetection, setLastDetection] = useState(null);

  // ============ DÉMARRER CAMÉRA ============
  useEffect(() => {
    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false
        });
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        setError("Impossible d'accéder à la caméra");
      }
    };

    startCamera();

    return () => {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
      if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    };
  }, []);

  // ============ BOUCLE AUTO ============
  useEffect(() => {
    if (!autoMode) {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
      return;
    }

    captureIntervalRef.current = setInterval(async () => {
      if (!videoRef.current || isProcessingRef.current) return;

      try {
        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth || 1280;
        canvas.height = videoRef.current.videoHeight || 720;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);

        isProcessingRef.current = true;
        setFrameCount(prev => prev + 1);

        // ✅ Envoi via pipeline_service.py
        const response = await attendanceAPI.recognize({ image_base64: imageBase64 });
        const data = response?.data;

        if (data.success && data.student) {
          setResult({
            success: true,
            name: data.student,
            email: data.email || 'N/A',
            confidence: (data.confidence * 100).toFixed(1),
            attendanceId: data.attendance_id,
            timestamp: new Date().toLocaleTimeString(),
            message: `${data.student} reconnu`
          });
          setLastDetection(new Date().toLocaleTimeString());
          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 3000);
        } else if (data.message) {
          console.log(`Non reconnu: ${data.message}`);
        }
      } catch (err) {
        console.warn("Erreur requête:", err.message);
      } finally {
        isProcessingRef.current = false;
      }
    }, 500);

    return () => {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
    };
  }, [autoMode]);

  // ============ CAPTURE MANUELLE ============
  const handleManualCapture = async () => {
    if (!videoRef.current || loading) return;

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.92);

      const response = await attendanceAPI.recognize({ image_base64: imageBase64 });
      const data = response?.data;

      if (data.success && data.student) {
        setResult({
          success: true,
          name: data.student,
          email: data.email,
          confidence: (data.confidence * 100).toFixed(1),
          attendanceId: data.attendance_id,
          timestamp: new Date().toLocaleTimeString(),
          message: `${data.student} reconnu`
        });
      } else {
        setError(data.message || 'Visage non reconnu');
        setResult({
          success: false,
          message: data.message || 'Non reconnu',
          confidence: ((data.confidence || 0) * 100).toFixed(1)
        });
      }
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || 'Erreur serveur');
    } finally {
      setLoading(false);
    }
  };

  // ============ ARRÊTER CAMÉRA ============
  const stopCamera = () => {
    if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
    if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    if (videoRef.current) videoRef.current.srcObject = null;
    setAutoMode(false);
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Reconnaissance Faciale</h1>

      <div style={styles.videoContainer}>
        <video ref={videoRef} autoPlay playsInline muted style={styles.video} />
        <div style={{
          ...styles.statusBadge,
          background: autoMode ? 'rgba(34, 197, 94, 0.9)' : 'rgba(107, 114, 128, 0.9)'
        }}>
          {autoMode ? 'Scanning...' : 'Pause'}
        </div>
        <div style={styles.frameCounter}>Frames: {frameCount}</div>
      </div>

      <div style={styles.actions}>
        <button onClick={handleManualCapture} disabled={loading} style={styles.btn}>
          {loading ? 'Traitement...' : 'Capturer'}
        </button>
        <button onClick={() => setAutoMode(!autoMode)} style={styles.btn}>
          {autoMode ? 'Arrêter Auto' : 'Démarrer Auto'}
        </button>
        <button onClick={stopCamera} style={styles.btn}>Fermer Caméra</button>
      </div>

      {lastDetection && <div style={styles.lastDetectionBox}>Dernière détection: {lastDetection}</div>}
      {error && <div style={styles.errorBox}>{error}</div>}
      {result && (
        <div style={{
          ...styles.resultBox,
          borderLeft: result.success ? '4px solid #10B981' : '4px solid #EF4444'
        }}>
          {result.success ? (
            <>
              <h3 style={{ color: '#10B981' }}>{result.message}</h3>
              <div style={styles.resultGrid}>
                <p><strong>Nom:</strong> {result.name}</p>
                <p><strong>Email:</strong> {result.email}</p>
                <p><strong>Confiance:</strong> {result.confidence}%</p>
                <p><strong>ID Présence:</strong> {result.attendanceId}</p>
                <p><strong>Heure:</strong> {result.timestamp}</p>
              </div>
            </>
          ) : (
            <>
              <h3 style={{ color: '#EF4444' }}>Non Reconnu</h3>
              <p>{result.message}</p>
              <p>Confiance: {result.confidence}%</p>
            </>
          )}
        </div>
      )}

      <div style={styles.debugBox}>
        <p><strong>Mode Auto:</strong> {autoMode ? 'ON' : 'OFF'}</p>
        <p><strong>Frames traités:</strong> {frameCount}</p>
        <p><strong>En traitement:</strong> {isProcessingRef.current ? 'OUI' : 'NON'}</p>
      </div>
    </div>
  );
};

// ✅ Définition des styles
// ✅ Définition des styles
const styles = {
  container: { padding: '20px', fontFamily: 'Arial, sans-serif', maxWidth: '800px', margin: '0 auto' },
  title: { fontSize: '1.5rem', marginBottom: '20px', textAlign: 'center' },
  videoContainer: { position: 'relative', display: 'inline-block', border: '2px solid #ccc', borderRadius: '8px' },
  video: { width: '640px', height: '360px', background: '#000', borderRadius: '8px' },
  statusBadge: { position: 'absolute', top: '10px', left: '10px', padding: '5px 10px', color: '#fff', borderRadius: '4px', fontWeight: 'bold' },
  frameCounter: { position: 'absolute', bottom: '10px', left: '10px', color: '#fff', background: 'rgba(0,0,0,0.5)', padding: '3px 8px', borderRadius: '4px' },
  actions: { marginTop: '20px', display: 'flex', gap: '10px', justifyContent: 'center' },
